SELECT c.owner,c.table_name,c.constraint_name,cc.position,cc.column_name,r.table_name referenced_table,rcc.column_name referenced_column,c.delete_rule,c.status FROM all_constraints c JOIN all_cons_columns cc ON cc.owner=c.owner AND cc.constraint_name=c.constraint_name JOIN all_constraints r ON r.owner=c.r_owner AND r.constraint_name=c.r_constraint_name JOIN all_cons_columns rcc ON rcc.owner=r.owner AND rcc.constraint_name=r.constraint_name AND rcc.position=cc.position WHERE c.owner=UPPER('&OWNER') AND c.constraint_type='R' ORDER BY c.table_name,c.constraint_name,cc.position;
